			t.Errorf("claude model %q Billing = %q, want subscription", info.ID, info.Billing)
		}
		if info.Power > 0 {
			sawPower = true
		}
	}
	if !sawPower {
		t.Errorf("want at least one subscription tier with Power metadata populated, got %v", modelInfoDebug(infos))
	}
}

